ALTER POLICY "trip_revision_via_trip" ON "trip_revision" TO authenticated USING (exists (select 1 from "trip" where "trip"."id" = "trip_revision"."trip_id" and "trip"."owner_id" = (select auth.uid()))) WITH CHECK (exists (select 1 from "trip" where "trip"."id" = "trip_revision"."trip_id" and "trip"."owner_id" = (select auth.uid())) and ("trip_revision"."planning_run_id" is null or exists (select 1 from "planning_run" where "planning_run"."id" = "trip_revision"."planning_run_id" and "planning_run"."trip_id" = "trip_revision"."trip_id")));